"""QQ-姿态库的 HTTP 路由：索引、图片、缩略图、导入、删除。

前端画廊通过 ``/qq_gulipose/*`` 取数据；所有写操作都限制在用户数据目录里，
不碰插件目录，也不接受任意路径。

**这个模块绝不能抛异常**：它在 ``node_modules/__init__.py`` 里被导入，一旦
炸掉整个包就注册不上，ComfyUI 里所有节点会变成 ``frontend_only``、控件全
变 ``UNKNOWN``（2026-10 踩过一次）。所以导入即可用的部分只有纯函数，
路由注册整段包在 try/except 里。
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

try:  # 包内导入（ComfyUI 正常加载）
    from . import guli_pose_db as db
except ImportError:  # pragma: no cover - 测试里按独立模块加载
    import guli_pose_db as db  # type: ignore[no-redef]

PREFIX = "/qq_gulipose"
#: 单张上传上限 200 MB。
MAX_UPLOAD = 200 * 1024 * 1024


def _index_payload(lib: str) -> dict[str, Any]:
    data = db.index(lib)
    return {
        "lib": lib,
        "name": db.lib_name(lib),
        "generated": data.get("generated"),
        "angles": data.get("angles") or [],
        "series": data.get("series") or [],
        "poses": data.get("poses") or [],
        "all": db.ALL,
        "randomAngle": db.RANDOM_ANGLE,
        "customSeries": db.CUSTOM_SERIES_KEY,
    }


def register() -> None:
    """挂到 ComfyUI 的 PromptServer 上；任何一步不可用都静默跳过。

    必须整段 try/except：这里抛出的异常会顺着 ``node_modules/__init__.py``
    冒到顶，导致整个包导入失败、全部节点消失。
    """
    try:
        from aiohttp import web
        from server import PromptServer
    except Exception:
        return
    server = getattr(PromptServer, "instance", None)
    if server is None:
        return
    routes = getattr(server, "routes", None)
    if routes is None:
        return
    for lib in db.LIB_DIRS:
        try:
            _register_lib(web, routes, lib)
        except Exception as err:  # 一个库挂不上不影响其它库，更不影响节点
            print(f"[QQ-姿态库] 路由注册失败（{lib}）：{err}", flush=True)


def _register_lib(web, routes, lib: str) -> None:
    def json_response(data: Any):
        return web.json_response(
            data, dumps=lambda obj: json.dumps(obj, ensure_ascii=False)
        )

    def safe_under(root: Path, name: str) -> Path:
        """root 下的目标路径；越界一律拒绝。"""
        resolved_root = root.resolve()
        target = (resolved_root / Path(str(name or "")).name).resolve()
        if target.parent != resolved_root:
            raise web.HTTPForbidden(text="越界路径")
        return target

    @routes.get(f"{PREFIX}/{lib}/index.json")
    async def get_index(_request):  # noqa: ANN001
        return json_response(_index_payload(lib))

    @routes.get(f"{PREFIX}/{lib}/img/{{name}}")
    async def get_image(request):  # noqa: ANN001
        target = safe_under(db.LIB_DIRS[lib]["builtin"], request.match_info.get("name", ""))
        if not target.is_file():
            raise web.HTTPNotFound(text="文件不存在")
        return web.FileResponse(target)

    @routes.get(f"{PREFIX}/{lib}/custom/{{name}}")
    async def get_custom_image(request):  # noqa: ANN001
        target = safe_under(db.custom_dir(lib), request.match_info.get("name", ""))
        if not target.is_file():
            raise web.HTTPNotFound(text="文件不存在")
        return web.FileResponse(target)

    @routes.get(f"{PREFIX}/{lib}/custom/thumbs/{{name}}")
    async def get_custom_thumb(request):  # noqa: ANN001
        path = db.ensure_thumb(request.match_info.get("name", ""), lib, custom=True)
        if path is None:
            raise web.HTTPNotFound(text="缩略图不可用")
        return web.FileResponse(path)

    @routes.get(f"{PREFIX}/{lib}/thumbs/{{name}}")
    async def get_thumb(request):  # noqa: ANN001
        path = db.ensure_thumb(request.match_info.get("name", ""), lib)
        if path is None:
            raise web.HTTPNotFound(text="缩略图不可用")
        return web.FileResponse(path)

    @routes.post(f"{PREFIX}/{lib}/custom/upload")
    async def upload(request):  # noqa: ANN001
        reader = await request.multipart()
        saved: list[str] = []
        name = cat = angle = ""
        files: list[tuple[str, bytes]] = []
        async for part in reader:
            if part.name == "name":
                name = (await part.text()).strip()
            elif part.name == "cat":
                cat = (await part.text()).strip()
            elif part.name == "angle":
                angle = (await part.text()).strip()
            elif part.name == "file":
                data = await part.read(decode=False)
                if len(data) > MAX_UPLOAD:
                    raise web.HTTPRequestEntityTooLarge(text="图片太大")
                files.append((part.filename or "pose.png", data))
        for filename, data in files:
            try:
                saved.append(db.save_custom(filename, data, name, cat, angle, lib))
            except Exception as err:
                print(f"[QQ-姿态库] 保存失败 {filename}：{err}", flush=True)
        if not saved:
            raise web.HTTPBadRequest(text="没有收到可保存的图片")
        return json_response({"saved": saved, "index": _index_payload(lib)})

    @routes.post(f"{PREFIX}/{lib}/custom/delete")
    async def delete(request):  # noqa: ANN001
        try:
            payload = await request.json()
        except Exception:
            raise web.HTTPBadRequest(text="请求体不是 JSON")
        name = str(payload.get("name") or "")
        if not db.delete_custom(name, lib):
            raise web.HTTPNotFound(text="文件不存在")
        return json_response({"deleted": name, "index": _index_payload(lib)})


__all__ = ["PREFIX", "register"]
